  "case_id": "case-health-covid19-response-process-flow",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "A1-portrait",
    "audience": "public-exhibition",
    "tone": "professional, engaging",
    "venue": null
  },
  "brief": {
    "title": "COVID-19 Emergency Response: From Detection to Recovery",
    "one_liner": "A step-by-step overview of the WHO-guided process for detecting, responding to, and recovering from COVID-19 outbreaks.",
    "goal": "Viewers should understand the structured, multi-phase process that WHO recommends for managing COVID-19 — from surveillance and early detection through clinical management, public health measures, and long-term recovery — and appreciate the global coordination involved."
  },
  "sections": [
    {
      "id": "surveillance",
      "title": "Phase 1: Surveillance & Early Detection",
      "objective": "Show how disease signals are identified and confirmed through global and national surveillance systems."
    },
    {
      "id": "risk-assessment",
      "title": "Phase 2: Risk Assessment & Alert",
      "objective": "Explain the rapid risk assessment process and how alerts are communicated to member states and the public."
    },
    {
      "id": "response-operations",
      "title": "Phase 3: Response Operations & Clinical Management",
      "objective": "Outline the coordinated response including infection prevention, clinical care protocols, and health system readiness."
    },
    {
      "id": "public-health-measures",
      "title": "Phase 4: Public Health & Social Measures",
      "objective": "Describe community-level interventions such as testing, contact tracing, quarantine, and vaccination campaigns."
    },
    {
      "id": "recovery-resilience",
      "title": "Phase 5: Recovery & Health System Resilience",
      "objective": "Highlight the transition from emergency response to sustained recovery, including lessons learned and preparedness for future outbreaks."
    }
  ],
  "metrics": [
    {
      "label": "WHO Member States Coordinated",
      "value": "194"
    },
    {
      "label": "Technical Guidance Documents Issued",
      "value": "Over 200"
    },
    {
      "label": "WHO Regions Covered",
      "value": "6"
    },
    {
      "label": "COVID-19 Dashboard Data Points Tracked",
      "value": "Millions daily"
    },
    {
      "label": "Vaccines Delivered via COVAX (by mid-2023)",
      "value": "~1.9 billion doses"
    }
  ]
}

